"""OpenAI Batch API helper module for LangExtract.

This module provides batch inference support using the OpenAI Batch API. It
handles:
- File-based batch submission (JSONL upload)
- Job polling and result extraction
- Order preservation across batch processing via custom IDs
- Optional job splitting into sub-batches
"""

from __future__ import annotations

import collections.abc
import dataclasses
import io
import json
import time
from typing import Any, Callable, Sequence

from absl import logging

from langextract.core import exceptions

_ENDPOINT = "/v1/chat/completions"
_COMPLETION_WINDOW = "24h"
_KEY_IDX = "idx-"

# Terminal batch job states.
_TERMINAL_OK = frozenset({"completed"})
_TERMINAL_FAIL = frozenset({"failed", "expired", "cancelled"})


def _custom_id(idx: int) -> str:
  """Build the custom ID used to track a prompt's original position."""
  return f"{_KEY_IDX}{idx:06d}"


@dataclasses.dataclass
class BatchConfig:
  """Define and validate OpenAI Batch API configuration.

  Attributes:
    enabled: Whether batch mode is enabled.
    threshold: Minimum prompts required to trigger batch processing.
    completion_window: Batch completion window. Only '24h' is supported.
    poll_interval: Seconds between job status checks.
    timeout: Maximum seconds to wait for job completion. Defaults to more than
      24 hours because the OpenAI Batch API allows jobs up to 24h to run.
    max_requests_per_job: Max requests allowed in one batch job.
    metadata: Optional metadata forwarded to the batch job creation call.
    on_job_create: Optional callback invoked with each created job object.
  """

  enabled: bool = False
  threshold: int = 25
  completion_window: str = _COMPLETION_WINDOW
  poll_interval: int | float = 30
  timeout: int | float = 90000
  max_requests_per_job: int = 50000
  metadata: dict | None = None
  on_job_create: Callable[[Any], None] | None = None

  def __post_init__(self):
    """Validate configuration early."""
    if self.completion_window != _COMPLETION_WINDOW:
      raise ValueError(
          "Unsupported completion_window "
          f"{self.completion_window!r}; only '24h' is supported."
      )

  @classmethod
  def from_dict(cls, obj: Any) -> "BatchConfig":
    """Coerce ``obj`` into a BatchConfig.

    Args:
      obj: A BatchConfig (returned unchanged), True/False (enabling or
        disabling batch mode), or a mapping of constructor kwargs.

    Returns:
      A BatchConfig instance.

    Raises:
      TypeError: If ``obj`` is not a BatchConfig, bool, or mapping.
    """
    if isinstance(obj, cls):
      return obj
    if obj is True:
      return cls(enabled=True)
    if obj is False:
      return cls(enabled=False)
    if isinstance(obj, collections.abc.Mapping):
      return cls(**dict(obj))
    raise TypeError(
        "batch must be a mapping, a bool, or a BatchConfig instance; got "
        f"{type(obj).__name__}"
    )


def _is_403(err: Exception) -> bool:
  """Return True if the exception represents an HTTP 403 (permission) error."""
  if getattr(err, "status_code", None) == 403:
    return True
  response = getattr(err, "response", None)
  if response is not None and getattr(response, "status_code", None) == 403:
    return True
  code = getattr(err, "code", None)
  if code in (403, "403"):
    return True
  return "403" in str(err)


def _response_to_text(resp: Any) -> str:
  """Extract the textual body from an OpenAI file-content response."""
  if resp is None:
    return ""
  if isinstance(resp, str):
    return resp
  if isinstance(resp, (bytes, bytearray)):
    return bytes(resp).decode("utf-8")

  text = getattr(resp, "text", None)
  if isinstance(text, str):
    return text

  content = getattr(resp, "content", None)
  if isinstance(content, str):
    return content
  if isinstance(content, (bytes, bytearray)):
    return bytes(content).decode("utf-8")

  read = getattr(resp, "read", None)
  if callable(read):
    data = read()
    if isinstance(data, (bytes, bytearray)):
      return bytes(data).decode("utf-8")
    if isinstance(data, str):
      return data

  return str(resp)


def _download_file(client: Any, file_id: str, cfg: BatchConfig) -> str:
  """Download a file's content, retrying on HTTP 403 errors.

  Retries the download up to three times (with two intermediate sleeps of
  ``cfg.poll_interval``) when a 403 permission error is encountered.

  Args:
    client: OpenAI client instance.
    file_id: ID of the file to download.
    cfg: Batch configuration (provides poll_interval).

  Returns:
    The decoded text content of the file.

  Raises:
    InferenceRuntimeError: If the download keeps failing with a 403 error.
  """
  attempts = 3
  for attempt in range(attempts):
    try:
      resp = client.files.content(file_id)
      return _response_to_text(resp)
    except exceptions.InferenceError:
      raise
    except Exception as e:  # pylint: disable=broad-except
      if _is_403(e):
        if attempt < attempts - 1:
          logging.warning(
              "Batch API: 403 while downloading file %s (attempt %d/%d); "
              "retrying after %s seconds.",
              file_id,
              attempt + 1,
              attempts,
              cfg.poll_interval,
          )
          time.sleep(cfg.poll_interval)
          continue
        raise exceptions.InferenceRuntimeError(
            "Failed to download batch output file "
            f"{file_id} after {attempts} attempts due to repeated 403 errors. "
            "Ensure the API key has the 'Files Read' permission (api.files.read)"
            " enabled.",
            original=e,
        ) from e
      raise
  # Unreachable, but keeps static analyzers satisfied.
  return ""


